from taf.ul.ettf.utils.provider import dryrun_is_set


class _Listener(object):
    ROBOT_LISTENER_API_VERSION = 3

    def __init__(self, always_on=False):
        self.ROBOT_LIBRARY_LISTENER = self if not dryrun_is_set() or always_on else None


class TestListener(_Listener):
    ROBOT_LIBRARY_SCOPE = "TEST CASE"


class SuiteListener(_Listener):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"


class GlobalListener(_Listener):
    ROBOT_LIBRARY_SCOPE = "GLOBAL"
